  1→/**
  2→ * @fileoverview User-facing formatter utilities for status/help/usage messages.
  3→ *
  4→ * This module produces structured text blocks sent directly to WhatsApp.
  5→ *
  6→ * @module agent/format
  7→ * @see {@link module:agent/whatsapp-format} Low-level text wrapping/normalization
  8→ */
  9→
 10→import { Session } from '../session/types.js';
 11→import { getTaskManager } from '../task/manager.js';
 12→import { VERSION, env } from '../config/env.js';
 13→
 14→/**
 15→ * Build the `/status` response from session and task state.
 16→ *
 17→ * @param session - Current user session
 18→ * @returns Formatted status message
 19→ */
 20→export async function formatStatus(session: Session): Promise<string> {
 21→  let message = `*FETCH SYSTEM REPORT* (${VERSION})\n`;
 22→  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
 23→  // Active project
 24→  message += `📂 *PROJECT CONTEXT*\n`;
 25→  if (session.currentProject) {
 26→    const type = session.currentProject.type === 'unknown' ? '' : ` (${session.currentProject.type})`;
 27→    message += `• *Name*: ${session.currentProject.name}${type}\n`;
 28→    message += `• *Path*: \`${session.currentProject.path}\`\n`;
 29→    if (session.currentProject.gitBranch) {
 30→      const gitIcon = session.currentProject.hasUncommitted ? '⚠️' : '✨';
 31→      message += `• *Branch*: \`${session.currentProject.gitBranch}\` ${gitIcon}\n`;
 32→    }
 33→  } else {
 34→    message += `• _No project currently sniffed out._\n`;
 35→  }
 36→  message += '\n';
 37→
 38→  // Current task
 39→  if (session.activeTaskId) {
 40→    const taskManager = await getTaskManager();
 41→    const task = taskManager.getTask(session.activeTaskId);
 42→    if (task) {
 43→      message += `🎯 *CURRENT FOCUS*\n`;
 44→      message += `• *Task*: ${task.goal.substring(0, 60)}${task.goal.length > 60 ? '...' : ''}\n`;
 45→      message += `• *State*: ${formatTaskStatus(task.status)}\n`;
 46→      message += '\n';
 47→    }
 48→  }
 49→
 50→  message += `━━━━━━━━━━━━━━━━━━━━━━━━━━━━\n`;
 51→
 52→  // Context — footerish
 53→  if (session.activeFiles.length > 0) {
 54→    message += `\n📁 *Sniffing around*: ${session.activeFiles.length} active files\n`;
 55→  }
 56→
 57→  return message;
 58→}
 59→
 60→/**
 61→ * Build the `/help` response.
 62→ *
 63→ * @returns Formatted command/tool overview
 64→ */
 65→export function formatHelp(): string {
 66→  return `*Fetch ${VERSION} — AI Coding Assistant*
 67→
 68→*Slash commands:*
 69→/stop - Cancel running task
 70→/undo - Undo last commit (soft reset)
 71→/clear - Clear conversation history
 72→/help - Show commands
 73→/status - Show system and task status
 74→/version - Show version
 75→/usage - Check API usage & spend
 76→/trust - Manage trusted numbers (owner only)
 77→
 78→*Tools:*
 79→- workspace_list: List projects
 80→- workspace_select: Switch project
 81→- workspace_status: Git status
 82→- workspace_create: New project
 83→- workspace_delete: Delete project
 84→- workspace_sync: Commit and push
 85→- workspace_publish: Create GitHub repo
 86→- task_create: Delegate coding task
 87→- task_status: Check task progress
 88→- task_cancel: Cancel task
 89→- task_respond: Respond to task
 90→- ask_user: Ask for clarification
 91→- report_progress: Send update
 92→- github_pr_create: Create pull request
 93→- github_pr_list: List pull requests
 94→- github_pr_view: View pull request
 95→- github_issue_create: Create GitHub issue
 96→- github_issue_list: List GitHub issues
 97→- github_branch_create: Create GitHub branch
 98→- github_action_status: Check CI/CD status
 99→- github_search_repos: Search GitHub repos
100→
101→*AI Harnesses:*
102→- Copilot 🎯: Fast suggestions, git commands
103→- Claude 🧠: Deep reasoning, refactoring
104→- Gemini ⚡: Quick fixes, explanations
105→- OpenCode 🔧: Multi-provider coding
106→- Codex 📦: Autonomous sandboxed tasks
107→
108→Just describe what you need in plain language!`;
109→}
110→
111→
112→/**
113→ * Convert internal task status to a user-facing label.
114→ *
115→ * @param status - Internal task status value
116→ * @returns Human-readable task status
117→ */
118→function formatTaskStatus(status: string): string {
119→  const statusMap: Record<string, string> = {
120→    'planning': '📋 Planning',
121→    'executing': '⚡ Executing',
122→    'awaiting_approval': '⏳ Waiting for approval',
123→    'paused': '⏸️ Paused',
124→    'completed': '✅ Completed',
125→    'failed': '❌ Failed',
126→    'aborted': '🛑 Aborted'
127→  };
128→  return statusMap[status] || status;
129→}
130→
131→/**
132→ * Build the `/usage` response from OpenRouter account metrics.
133→ *
134→ * @returns Formatted usage report, or an actionable error message
135→ */
136→export async function formatUsage(): Promise<string> {
137→  const apiKey = env.OPENROUTER_API_KEY;
138→  if (!apiKey) {
